on:
  push:
    branches:
      - main

jobs:
  merged-pr:
    if: |
      github.ref == 'refs/heads/main' &&
      !contains(github.event.head_commit.message, '[skip ci]') &&
      !contains(github.event.head_commit.message, 'chore(release)')

    runs-on: ubuntu-latest
    environment: production
    permissions:
      id-token: write
      contents: write

    steps:

      - name: Generate GitHub app token
        id: generate_app_token
        uses: actions/create-github-app-token@v1
        with:
          app-id: ${{ vars.HYPER_SDK_APP_ID }}
          private-key: ${{ secrets.HYPER_SDK_APP_PRIVATE_KEY }}

      - name: Checkout code
        uses: actions/checkout@v4
        with:
          token: ${{ steps.generate_app_token.outputs.token }}
          fetch-depth: 0

      - name: Install SSH key
        env:
          DEPLOY_KEY: ${{ secrets.HYPER_SDK_DEPLOY_KEY }}
        run: |
          # create .ssh
          mkdir -p ~/.ssh
          chmod 700 ~/.ssh

          # write private key
          echo "$DEPLOY_KEY" > ~/.ssh/id_ed25519
          chmod 600 ~/.ssh/id_ed25519

          # ensure github host key is known (avoid StrictHostKeyChecking prompt)
          ssh-keyscan github.com >> ~/.ssh/known_hosts
          chmod 644 ~/.ssh/known_hosts

      - name: Set up Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "24.11.0"
          registry-url: "https://registry.npmjs.org"

      - name: Install dependencies
        run: npm ci

      - name: Determine release type
        id: determine-release
        run: |
          shopt -s nocasematch

          COMMITS="$(git log --format=%B ${{ github.event.before }}..${{ github.sha }})"

          if [[ "$COMMITS" == *"[breaking]"* || "$COMMITS" == *"[major]"* ]]; then
            echo "release_type=major" >> "$GITHUB_OUTPUT"
          elif [[ "$COMMITS" == *"[minor]"* ]]; then
            echo "release_type=minor" >> "$GITHUB_OUTPUT"
          else
            echo "release_type=patch" >> "$GITHUB_OUTPUT"
          fi

          shopt -u nocasematch
        shell: bash

      - name: Conventional Changelog Action
        id: changelog
        uses: TriPSs/conventional-changelog-action@v5.1.0
        with:
          github-token: ${{ steps.generate_app_token.outputs.token }}
          release-count: 0
          skip-version-file: "true"
          skip-commit: "true"
          git-push: "false"
          skip-tag: "true"
          skip-bump: "true"
          output-file: "false"

      - name: Stash changes
        run: git reset --hard

      - name: git config
        run: |
          git config --local user.name 'hyper-sdk-app[bot]'
          git config --local user.email '163947841+hyper-sdk-app[bot]@users.noreply.github.com'

      - name: Run standard version
        id: standard-version
        run: |
          npx standard-version --release-as ${{ steps.determine-release.outputs.release_type }}
          echo "tag_name=$(git describe --abbrev=0 --tags)" >>$GITHUB_OUTPUT

      - name: Push tags and changelog
        run: git push --follow-tags origin main

      - name: create release
        uses: actions/create-release@v1
        env:
          GITHUB_TOKEN: ${{ steps.generate_app_token.outputs.token }}
        with:
          tag_name: "${{ steps.standard-version.outputs.tag_name }}"
          release_name: "${{ steps.standard-version.outputs.tag_name }}"
          body: "${{ steps.changelog.outputs.clean_changelog }}"

      - name: Publish package on NPM 📦
        run: npm publish --access public
