                            assert.equal(0, diff2.length, 'Following countries are not found on the website: ' + diff2);

                            stepCallback();
                        })
                        .catch(function (err) {
                            stepCallback(err);
                        });
                }
            ],
            function (err) {
                return done(err);
            }
        )
    });
